import * as React from "react";
import { Loader2, QrCode, ShieldCheck } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp";
import { cn } from "@/lib/utils";

export interface SetupMFAModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The QR code string/URL generated by the parent's API call */
  qrCode?: string;
  /** * The core verification logic. 
   * The modal manages the loading state automatically based on this promise.
   */
  onVerify: (code: string) => Promise<{ error: any; status: number; message: string; data?: any }>;
  /** Callback for when the user clicks 'Back' from the QR screen */
  onScanBack?: () => void;
  title?: string;
  description?: string;
  length?: number;
  defaultScreen?: "qrCode" | "verify";
}

export function SetupMFAModal({
  open,
  onOpenChange,
  qrCode,
  onVerify,
  onScanBack,
  title = "Set up Authenticator",
  description = "Scan the QR code with your authenticator app (like Google Authenticator or Authy).",
  length = 6,
  defaultScreen = "qrCode",
}: SetupMFAModalProps) {
  const [value, setValue] = React.useState("");
  const [step, setStep] = React.useState<"scan" | "verify">(defaultScreen === "qrCode" ? "scan" : "verify");
  const [loading, setLoading] = React.useState(false);
  const [errorMessage, setErrorMessage] = React.useState<string | null>(null);

  // Performance: Clean up state when modal visibility changes
  React.useEffect(() => {
    if (!open) {
      setValue("");
      setStep(defaultScreen === "qrCode" ? "scan" : "verify");
      setErrorMessage(null);
      setLoading(false);
    }
  }, [open]);

  const handleVerify = async (code: string) => {
    if (code.length !== length) return;
    
    setLoading(true);
    setErrorMessage(null);

    try {
      const result = await onVerify(code);
      
      if (result.error || result.status !== 200) {
        setErrorMessage(result.message || "Invalid verification code.");
      } else {
        // Success case is handled by the parent or by closing the modal
        onOpenChange(false);
      }
    } catch (err) {
      setErrorMessage("An unexpected error occurred. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    if (step === "verify") {
      setStep(defaultScreen === "qrCode" ? "scan" : "verify");
      setErrorMessage(null);
      setValue("");
      onScanBack?.();
    } else {
      onScanBack?.();
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {step === "scan" ? <QrCode className="h-5 w-5" /> : <ShieldCheck className="h-5 w-5" />}
            {step === "scan" ? title : "Verify Code"}
          </DialogTitle>
          <DialogDescription>
            {step === "scan" 
              ? description 
              : "Enter the 6-digit code from your app to complete setup."}
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col items-center justify-center py-6 gap-4">
          {step === "scan" ? (
            <div className="bg-white p-4 rounded-xl border-2 border-muted shadow-sm">
              {qrCode ? (
                <img src={qrCode} alt="MFA QR Code" className="h-48 w-48" />
              ) : (
                <div className="h-48 w-48 flex items-center justify-center bg-muted animate-pulse rounded-lg">
                  <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                </div>
              )}
            </div>
          ) : (
            <InputOTP
              maxLength={length}
              value={value}
              onChange={setValue}
              onComplete={handleVerify}
              disabled={loading}
              autoFocus
            >
              <InputOTPGroup className="gap-2">
                {Array.from({ length }).map((_, i) => (
                  <InputOTPSlot key={i} index={i} className="rounded-md border" />
                ))}
              </InputOTPGroup>
            </InputOTP>
          )}

          {errorMessage && (
            <p className="text-sm font-medium text-destructive animate-in fade-in slide-in-from-top-1">
              {errorMessage}
            </p>
          )}
        </div>

        <DialogFooter className="flex flex-col sm:flex-col gap-2">
          {step === "scan" ? (
            <Button 
              className="w-full" 
              onClick={() => setStep("verify")}
              disabled={!qrCode}
            >
              I've scanned the code
            </Button>
          ) : (
            <Button 
              className="w-full" 
              onClick={() => handleVerify(value)}
              disabled={loading || value.length !== length}
            >
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Complete Setup
            </Button>
          )}
          
          <Button
            variant="ghost"
            className="w-full"
            onClick={handleBack}
            disabled={loading}
          >
            {step === "verify" ? "Back" : "Cancel"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}